 public function draft(int $prediction,array $input):array {
  $this->authorize();abort_unless($this->can('fulfillment.manage'),403);$v=validator($input,['confirm'=>'required|accepted','quantity'=>'required|numeric|gt:0','review_token'=>'required|string|size:64','acknowledge_shortage'=>'sometimes|boolean'])->validate();return DB::transaction(function()use($prediction,$v){DB::table('companies')->where('id',Auth::user()->company_id)->lockForUpdate()->first();$protected=Prediction::v8()->whereNull('value->archived')->lockForUpdate()->findOrFail($prediction);Customer::whereKey($protected->entity_id)->lockForUpdate()->firstOrFail();Product::whereKey($protected->value['product_id'])->lockForUpdate()->firstOrFail();$r=$this->review($prediction,$v);abort_unless(hash_equals($r['review_token'],$v['review_token']),409,'Customer, price, quantity or available inventory changed. Review again before creating the draft.');abort_if($r['shortage']&&!$r['acknowledge_shortage'],422,'Acknowledge the stock shortage before creating a draft for human review.');$key='v8-draft-'.$prediction;$data=['customer_id'=>$r['customer_id'],'currency'=>$r['currency'],'payment_type'=>'cash','order_date'=>today()->toDateString(),'notes'=>'Human-reviewed Customer & Sales Intelligence opportunity #'.$prediction,'idempotency_key'=>$key,'items'=>[['product_id'=>$r['product_id'],'quantity'=>$r['quantity'],'unit'=>$r['unit'],'unit_price'=>$r['unit_price']]]];$order=app(OutboundService::class)->create($data);app(AnalyticsDataService::class)->audit('customer.intelligence.draft_reviewed',['prediction_id'=>$prediction,'order_id'=>$order->id,'quantity'=>$r['quantity']]);return ['order'=>$order->only(['id','order_number','status','total_amount']),'url'=>'/fulfillment?order='.$order->id,'qualification'=>$r['qualification']];});
 }
 private function events(Snapshot $r,?Snapshot $old):void {
  $before=collect($old?->evidence['profiles']??[])->keyBy('id');$events=[];foreach($r->evidence['profiles'] as $p)if(in_array($p['state'],['AT_RISK','INACTIVE'])&&($before[$p['id']]['state']??null)!==$p['state'])$events[]=['activity_changed',$p['id'],['state'=>$p['state'],'confidence'=>$p['cadence']['confidence']]];
  $keys=array_column($old?->evidence['opportunities']??[],'key');foreach($r->evidence['opportunities'] as $o)if(!in_array($o['key'],$keys))$events[]=[$o['kind']==='REORDER_OPPORTUNITY'?'reorder_window':'sales_opportunity',$o['customer_id'],['product_id'=>$o['product_id'],'confidence'=>$o['confidence']]];
  if($old&&abs(($r->evidence['concentration']['top_shares'][5]??0)-($old->evidence['concentration']['top_shares'][5]??0))>=5)$events[]=['concentration_changed',0,['change_points'=>round(($r->evidence['concentration']['top_shares'][5]??0)-($old->evidence['concentration']['top_shares'][5]??0),1)]];
  foreach($r->evidence['profiles'] as $profile)if(in_array($profile['state'],['AT_RISK','INACTIVE'])&&str_starts_with($profile['segment'],'HIGH_VALUE')&&($before[$profile['id']]['state']??null)!==$profile['state'])$events[]=['high_value_inactivity',$profile['id'],['state'=>$profile['state'],'confidence'=>$profile['cadence']['confidence']]];
  foreach($events as [$kind,$id,$meta]){app(BusinessEventService::class)->record('customer.intelligence.'.$kind,$r,'Customer sales review',$meta+['customer_id'=>$id],'customer-v8:'.$r->version.':'.$kind.':'.$id.':'.($meta['product_id']??0));$family=$kind==='high_value_inactivity'?'activity_changed':$kind;$key=hash('sha256','customer-v8:'.$r->company_id.':'.$family.':'.$id.':'.($meta['product_id']??0));$task=OperationalTask::firstOrCreate(['dedupe_key'=>$key],['title'=>'Review customer sales: '.str_replace('_',' ',$kind),'description'=>'Review evidence in Customer & Sales Intelligence. No automatic contact or order.','priority'=>'normal','assigned_role'=>'admin','source_type'=>'CustomerSalesSnapshot','source_id'=>$r->id,'created_by'=>Auth::id(),'due_at'=>today()->addDay()]);if(in_array($task->status,['completed','cancelled']))$task->update(['status'=>'open','source_id'=>$r->id,'completed_at'=>null]);}
 }
 public function scheduled(bool $force=false):int {$previous=Auth::user();$done=0;$start=microtime(true);try{foreach(Company::orderBy('id')->cursor() as $company){if(microtime(true)-$start>config('customer_intelligence.worker_seconds'))break;$actor=User::withoutGlobalScopes()->where('company_id',$company->id)->whereIn('role',['admin','manager'])->where('is_active',true)->first();if(!$actor)continue;Auth::setUser($actor);try{$r=Snapshot::whereNull('evidence->archived')->latest('id')->first();if($force||!$r||($r->evidence['calculation_version']??null)!==config('customer_intelligence.version')||$r->evidence_cutoff->lt(now()->subMinutes(60))||Cache::has('customer-sales-dirty:'.$company->id)){$this->refresh();$done++;}}catch(\Throwable $e){Log::warning('Customer intelligence refresh deferred.',['company_id'=>$company->id,'error'=>$e->getMessage()]);}}}finally{$previous?Auth::setUser($previous):Auth::forgetUser();}return $done;}
}
